package run.ikaros.password; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/password/vaults/{vaultId}/import") public class PasswordImportController{private final PasswordImportService service;public PasswordImportController(PasswordImportService s){service=s;}@PostMapping public Mono<PasswordImportResult> importVault(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody EncryptedVaultExport export){return service.importVault(a,vaultId,export);}}
